import java.util.*; import java.io.*; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int N = Integer.parseInt(st.nextToken()); int M = Integer.parseInt(st.nextToken()); int T = Integer.parseInt(st.nextToken()); int C = Integer.parseInt(st.nextToken()); List<Integer>[] adj = new ArrayList[N + 1]; for (int i = 1; i <= N; i++) adj[i] = new ArrayList<>(); for (int i = 0; i < M; i++) { st = new StringTokenizer(br.readLine()); int u = Integer.parseInt(st.nextToken()); int v = Integer.parseInt(st.nextToken()); adj[u].add(v); adj[v].add(u); } for (int i = 1; i <= N; i++) Collections.sort(adj[i]); st = new StringTokenizer(br.readLine()); int start = Integer.parseInt(st.nextToken()); int end = Integer.parseInt(st.nextToken()); int[] dist = new int[N + 1]; int[] parent = new int[N + 1]; Arrays.fill(dist, Integer.MAX_VALUE); Arrays.fill(parent, -1); Queue<Integer> q = new LinkedList<>(); dist[start] = 0; q.add(start); while (!q.isEmpty()) { int u = q.poll(); if (u == end) break; int currentTime = dist[u]; for (int v : adj[u]) { int wait = 0; if ((currentTime / T) % 2 != 0) { wait = T - (currentTime % T); } int nextTime = currentTime + wait + C; if (nextTime < dist[v]) { dist[v] = nextTime; parent[v] = u; q.add(v); } } } List<Integer> path = new ArrayList<>(); for (int at = end; at != -1; at = parent[at]) path.add(at); Collections.reverse(path); System.out.println(path.size()); StringBuilder sb = new StringBuilder(); for (int i = 0; i < path.size(); i++) { sb.append(path.get(i)).append(i == path.size() - 1 ? "" : " "); } System.out.println(sb.toString()); } }